import{_ as e,o,c as t,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"Volume Shadow Copies with CephFS- A Samba-Centric Approach - Shwetha Acharya, IBM","description":"","frontmatter":{"title":"Volume Shadow Copies with CephFS- A Samba-Centric Approach - Shwetha Acharya, IBM","date":"2025-01-23T00:00:00.000Z","updated":"2025-01-24T00:00:00.000Z","tags":["CephFS","Samba integration","Volume Shadow Copy Service (VSSS)","Data snapshots","Backup and recovery"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Volume_Shadow_Copies_with_CephFS_-_A_Samba-Centric_Approach_-_Shwetha_Acharya_IBM.md","filePath":"posts/2025/Volume_Shadow_Copies_with_CephFS_-_A_Samba-Centric_Approach_-_Shwetha_Acharya_IBM.md","lastUpdated":1780459816000}'),S={name:"posts/2025/Volume_Shadow_Copies_with_CephFS_-_A_Samba-Centric_Approach_-_Shwetha_Acharya_IBM.md"};function i(l,a,s,p,n,h){return o(),t("div",null,[...a[0]||(a[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题</strong>: Ceph与Samba集成中的Volume Shadow Copy Service (VSSS)</p><p><strong>主讲人</strong>: Sha Aaria (IBM Ceph工程团队)</p><p><strong>会议内容总结</strong>:</p><ol><li><p><strong>背景介绍</strong>:</p><ul><li><strong>SMB与Samba</strong>: SMB是Windows系统中用于文件共享的协议，而Linux系统通常使用NFS。Samba是一个开源项目，允许Linux系统与Windows环境集成，使Windows客户端能够访问Linux服务器上的文件。</li><li><strong>Volume Shadow Copy Service (VSSS)</strong>: VSSS是Windows系统中的一个服务，用于创建数据的快照，以便在不影响正在进行的操作的情况下进行快速恢复和回滚。Ceph提供了类似的功能，但VSSS提供了更高效的解决方案，确保数据一致性并协调所有相关组件的交互。</li></ul></li><li><p><strong>Ceph与VSSS的集成</strong>:</p><ul><li><strong>组件</strong>: VSSS服务、VSSS请求者、VSSS写入者、VSSS提供者。Ceph在集成中扮演VSSS写入者和提供者的角色，确保数据一致性并创建快照。</li><li><strong>FSRVP协议</strong>: VSSS使用FSRVP（File Server Remote VSS Protocol）协议在不同组件之间进行通信，支持快照的创建、删除和枚举。</li></ul></li><li><p><strong>Samba配置</strong>:</p><ul><li><strong>VFS模块</strong>: Samba中的VFS模块用于访问Ceph快照，需在Samba配置文件中启用相关模块（如VFS Ceph snapshots）。</li><li><strong>配置示例</strong>: 提供了两种配置方式，一种是使用libcephfs库访问文件，另一种是使用内核挂载。</li></ul></li><li><p><strong>演示</strong>:</p><ul><li>展示了一个三节点Ceph集群的设置，如何在Linux服务器上创建快照，并通过Windows客户端访问和恢复这些快照。</li></ul></li><li><p><strong>未来计划</strong>:</p><ul><li>计划将VSSS功能默认支持在共享文件夹中。</li><li>增加对管理模块的支持，包括NFS Ganesha和Samba的快照管理。</li><li>进行更多测试和Bug修复。</li></ul></li><li><p><strong>Q&amp;A</strong>:</p><ul><li>讨论了内核挂载与libcephfs的使用区别。</li><li>确认当前版本的Samba已经支持VSSS功能，但尚未完全测试，不建议在生产环境中使用。</li></ul></li></ol><p><strong>后续行动计划</strong>:</p><ul><li>社区成员可以测试该功能并报告Bug，帮助改进VSSS与Ceph的集成。</li><li>未来版本将默认支持VSSS功能，并增加管理模块的支持。</li></ul><p><strong>参考链接</strong>:</p><ul><li>Ceph相关问题报告链接: <a href="https://tracker.ceph.com" target="_blank" rel="noreferrer">tracker.ceph.com</a></li><li>Bug报告链接: <a href="https://bugs.samba.org" target="_blank" rel="noreferrer">bugs.samba.org</a></li></ul><p><strong>会议结束</strong></p>',10)])])}const c=e(S,[["render",i]]);export{g as __pageData,c as default};
